lr() { kubectl --context main -n team-red get limitrange team-red-defaults -o jsonpath="{.spec.limits[?(@.type==\"Container\")].$1}" 2>/dev/null; }
check "LimitRange team-red-defaults: default requests cpu 100m / memory 128Mi" bash -c "[ \"\$(kubectl --context main -n team-red get limitrange team-red-defaults -o jsonpath='{.spec.limits[?(@.type==\"Container\")].defaultRequest.cpu} {.spec.limits[?(@.type==\"Container\")].defaultRequest.memory}')\" = '100m 128Mi' ]"
check "LimitRange team-red-defaults: default limit memory 256Mi, max memory 512Mi" bash -c "[ \"\$(kubectl --context main -n team-red get limitrange team-red-defaults -o jsonpath='{.spec.limits[?(@.type==\"Container\")].default.memory} {.spec.limits[?(@.type==\"Container\")].max.memory}')\" = '256Mi 512Mi' ]"
check "Deployment worker runs 4 ready pods (Deployment unchanged)" bash -c "deploy_ready main worker team-red 4 && [ -z \"\$(kubectl --context main -n team-red get deploy worker -o jsonpath='{.spec.template.spec.containers[0].resources}' | tr -d '{}')\" ]"
check "quota-used.txt holds the quota's current requests.memory usage" bash -c "file_eq '$ANSWERS/quota-used.txt' \"\$(kubectl --context main -n team-red get resourcequota team-red-quota -o jsonpath='{.status.used.requests\.memory}')\""
